using OcctSharp.StepCafWorkspaces;
using OcctSharp.DocumentProjections;
using OcctSharp.XdeMetadataWorkspaces;
namespace OcctSharp.Tests.Shared;
internal static class BatchBJLocalStepWorkflow {
 internal static string Fixture=>Path.Combine(AppContext.BaseDirectory,"Fixtures","LocalStep");
 internal static readonly string[] AssemblyFiles=["assembly.step","piece_part.stp"];
 internal static void Verify(LocalStepTransferResult result){if(!result.Completed||result.Document is null||result.Roots.Count!=1||result.Roots.Any(x=>!x.NativeSucceeded||x.Failure is not null)||result.FreeRoots.Count!=1)throw new InvalidOperationException("BJ selected root transfer failed.");var leaf=result.Files.Single(x=>x.FileName=="piece_part.stp");if(!leaf.Loaded||leaf.LoadStatus!=1||leaf.NativeTransferSucceeded!=true||leaf.ImportedLabelEntry is null)throw new InvalidOperationException("BJ actual external-file status/label failed.");if(result.Occurrences.Count!=2||result.Occurrences[0].Entry==result.Occurrences[1].Entry||result.Occurrences[0].DefinitionEntry!=result.Occurrences[1].DefinitionEntry||result.Occurrences.Any(x=>x.ParentEntry!=result.FreeRoots[0].Entry))throw new InvalidOperationException("BJ imported repeated occurrence/shared definition identity failed.");using var context=DocumentProjectionContext.Bind(result.Document);using var metadata=XdeMetadataContext.Bind(context);var target=metadata.Snapshot([context.GetLabel(result.Occurrences[0].DefinitionEntry)]).Targets.Single();var color=target.General??target.Surface;if(color is null||Math.Abs(color.Red-.25)>1e-6||Math.Abs(color.Green-.5)>1e-6||Math.Abs(color.Blue-.75)>1e-6)throw new InvalidOperationException("BJ imported actual external definition color failed.");using var first=result.CopyOccurrence(1);using var second=result.CopyOccurrence(2);if(!first.IsValid||!second.IsValid||first.FaceCount!=6||second.FaceCount!=6||Math.Abs(first.GetBoundingBox().Minimum.X-second.GetBoundingBox().Minimum.X)<9)throw new InvalidOperationException("BJ actual occurrence placement/geometry failed.");}
 internal static void Run(){var manifest=LocalStepAssemblyWorkspace.CaptureManifest(Fixture,AssemblyFiles);using var workspace=LocalStepAssemblyWorkspace.Open(Fixture,"assembly.step",manifest);if(workspace.Roots.Count!=1||workspace.Files.Count!=2||workspace.Files.Single(x=>x.FileName=="assembly.step").References.Single().FileName!="piece_part.stp")throw new InvalidOperationException("BJ graph/source diagnostic failed.");using var result=workspace.Transfer([workspace.Roots[0].Id]);workspace.Dispose();Verify(result);using var copied=result.CopyFreeRoot(1);using var context=DocumentProjectionContext.Bind(result.Document!);var root=context.GetLabel(result.FreeRoots[0].Entry);result.Document!.NewCommand();context.ReplaceCollection(root,DirectCollections.List<string>(workspace.Files.Select(x=>x.Sha256)));if(!result.Document.CommitCommand())throw new InvalidOperationException("BJ BI imported exact domain projection failed.");var detached=context.ReadCollection(root,DirectCollectionKind.StringList)!.Value;result.Dispose();if(detached.Count!=2||!copied.IsValid||copied.FaceCount!=12)throw new InvalidOperationException("BJ copied import/document lifetime failed.");}
}
